messages.content:
{
  "chapter": "政事第三",
  "liu_annotations": [
    {
      "annotation_id": "annotation-001",
      "text": "(曰山濤字/虞預晉書)"
    },
    {
      "annotation_id": "annotation-002",
      "text": "(貧少有器量宿士猶不慢之年十七宗人謂宣帝曰/巨源河内懐人祖本郡孝廉父曜宛句令濤蚤孤而)"
    },
    {
      "annotation_id": "annotation-003",
      "text": "(此快人邪好荘老與嵇康善為河内從事與石鑒共/濤當與景文共綱紀天下者也帝戱曰卿小族那得)"
    },
    {
      "annotation_id": "annotation-004",
      "text": "(意鑒曰宰相三日不朝與尺一令歸第君何慮焉濤/傳宿濤夜起蹋鑒曰今何等時而眠也知太傅卧何)"
    },
    {
      "annotation_id": "annotation-005",
      "text": "(隱身不交世務累遷吏部尚書僕射太子少傅司徒/曰咄石生無事馬蹄閒也投傳而去果有曹爽事遂)"
    },
    {
      "annotation_id": "annotation-006",
      "text": "(薨諡康侯/年七十九)"
    },
    {
      "annotation_id": "annotation-007",
      "text": "(曰閣東有大牛王濟鞅裴楷鞦和嶠刺促不得休/王隱晉書曰初濤領吏部潘岳内非之宻為作謡)"
    },
    {
      "annotation_id": "annotation-008",
      "text": "(選非望路絶故貽是言/竹林七賢論曰濤之處)"
    },
    {
      "annotation_id": "annotation-009",
      "text": "(字正叔滎陽/文士傳曰尼)"
    },
    {
      "annotation_id": "annotation-010",
      "text": "(尼少有清才文詞温雅初應州辟終太常卿/人祖朂尚書左丞父滿平原太守並以文學稱)"
    }
  ],
  "story_id": "03-zhengshi-005",
  "story_text": "山公以器重朝望年踰七十猶知管時任\n\n\n\n\n\n貴勝年少若和裴王之徒並共宗詠有署\n閣柱曰閣東有大牛和嶠鞅裴楷鞦王濟剔嬲不得\n休\n或云潘尼作之"
}
